package com.healthcare.portal.dto; import com.healthcare.portal.entity.TimeSlot; import java.time.LocalDate; import java.time.LocalTime; public record TimeSlotResponse(Long id,Long doctorId,LocalDate date,LocalTime startTime,LocalTime endTime,boolean booked){public static TimeSlotResponse from(TimeSlot s){return new TimeSlotResponse(s.getId(),s.getDoctor().getId(),s.getSlotDate(),s.getStartTime(),s.getEndTime(),Boolean.TRUE.equals(s.getIsBooked()));}}
